import {
  BadRequestException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { Prisma } from '@prisma/client';
import { ApproveCertificateImportDto } from './dto';
import {
  CertificateBulkImportAppliedEntityType,
  CertificateBulkImportItemStatus,
  CertificateBulkImportItemType,
} from './certificate-bulk-imports.types';
import {
  civilDateFromDbDate,
  classifyCertificateImportYear,
  utcCivilDate,
} from './certificate-import-year-resolver.service';
import { assertClassCertificateHistoricalAge } from './class-certificate-historical-age';

type CertificateImportApplicationTransaction = Pick<
  Prisma.TransactionClient,
  | 'certificate_bulk_import_items'
  | 'certificate_bulk_import_batches'
  | 'users_honors'
  | 'evidence_files'
  | 'ecclesiastical_years'
  | 'enrollments'
  | 'classes'
  | 'users'
  | 'investiture_validation_history'
  | 'certificate_bulk_import_item_events'
>;

const GUIDE_MAJOR_ASSET_CODE = 'GM-01';
const INSTITUTIONAL_CLASS_ASSET_CODES = new Set(['GM-02', 'GM-03']);

const REVIEWABLE_ITEM_STATUSES = [
  CertificateBulkImportItemStatus.SUBMITTED,
  CertificateBulkImportItemStatus.RESUBMITTED,
];

type ExistingClassEnrollment = {
  enrollment_id: number;
  ecclesiastical_year_id: number;
  investiture_status: string;
  investiture_date: Date | null;
  record_kind: string;
  modified_at: Date;
};

type AccreditedEnrollment = {
  enrollmentId: number;
  recordHistory: boolean;
  historyComment?: string;
};

type EnrollmentReconciliation = {
  enrollmentId?: number;
  expectedModifiedAt?: string;
};

type CertificateImportItemWithBatch = {
  item_id: string;
  item_type: string;
  honor_id?: number | null;
  class_id?: number | null;
  completed_at?: Date | null;
  status?: string | null;
  applied_entity_type?: string | null;
  applied_entity_id?: number | null;
  batch: {
    batch_id: string;
    user_id: string;
    files: Array<{
      file_url: string;
      file_name: string;
      file_type: string;
      uploaded_by_id: string;
    }>;
  };
};

@Injectable()
export class CertificateBulkImportApplicationService {
  constructor(private readonly prisma: PrismaService) {}

  async approveItem(
    reviewerId: string,
    batchId: string,
    itemId: string,
    dto: ApproveCertificateImportDto,
  ) {
    return this.prisma.$transaction((tx) =>
      this.approveItemInTransaction(tx, reviewerId, batchId, itemId, dto),
    );
  }

  async approveItemInTransaction(
    tx: CertificateImportApplicationTransaction,
    reviewerId: string,
    batchId: string,
    itemId: string,
    dto: ApproveCertificateImportDto,
  ) {
    const item = await this.findSubmittedItem(tx, batchId, itemId);

    if (item.applied_entity_id) {
      return item;
    }

    const claimed = await tx.certificate_bulk_import_items.updateMany({
      where: {
        item_id: item.item_id,
        active: true,
        status: { in: REVIEWABLE_ITEM_STATUSES },
        applied_entity_id: null,
      },
      data: { revision: { increment: 1 } },
    });
    if (claimed.count !== 1) {
      const current = await this.findSubmittedItem(tx, batchId, itemId);
      if (current.applied_entity_id) {
        return current;
      }
      throw new BadRequestException('CERTIFICATE_IMPORT_ITEM_NOT_REVIEWABLE');
    }

    if (!item.completed_at) {
      throw new BadRequestException('CERTIFICATE_IMPORT_ITEM_MISSING_DATE');
    }

    if (item.item_type === CertificateBulkImportItemType.HONOR) {
      return this.approveHonorItem(tx, item, reviewerId, dto.comment);
    }

    if (item.item_type === CertificateBulkImportItemType.CLASS) {
      return this.approveClassItem(tx, item, reviewerId, dto);
    }

    throw new BadRequestException('CERTIFICATE_IMPORT_ITEM_TYPE_INVALID');
  }

  private async approveHonorItem(
    tx: CertificateImportApplicationTransaction,
    item: CertificateImportItemWithBatch,
    reviewerId: string,
    comment?: string,
  ) {
    if (!item.honor_id) {
      throw new BadRequestException('CERTIFICATE_IMPORT_ITEM_MISSING_HONOR');
    }

    const primaryFile = this.primaryFile(item);
    const now = new Date();
    const existingUserHonor = await tx.users_honors.findFirst({
      where: {
        user_id: item.batch.user_id,
        honor_id: item.honor_id,
      },
      select: {
        user_honor_id: true,
        active: true,
        date: true,
        validation_status: true,
      },
    });

    if (
      existingUserHonor?.date &&
      existingUserHonor.validation_status === 'APPROVED' &&
      civilDateFromDbDate(existingUserHonor.date) !==
        civilDateFromDbDate(item.completed_at)
    ) {
      throw new BadRequestException('CERTIFICATE_IMPORT_FINAL_DATE_CONFLICT');
    }

    const identicalHonor =
      !!existingUserHonor?.date &&
      civilDateFromDbDate(existingUserHonor.date) ===
        civilDateFromDbDate(item.completed_at);

    const userHonor = existingUserHonor
      ? await tx.users_honors.update({
          where: { user_honor_id: existingUserHonor.user_honor_id },
          data: identicalHonor
            ? {
                active: true,
                certificate: primaryFile.file_url,
                images: item.batch.files.map((file) => file.file_url),
              }
            : {
                active: true,
                validate: true,
                validation_status: 'APPROVED',
                submitted_at: now,
                validated_by_id: reviewerId,
                validated_at: now,
                rejection_reason: null,
                certificate: primaryFile.file_url,
                images: item.batch.files.map((file) => file.file_url),
                date: item.completed_at!,
              },
        })
      : await tx.users_honors.create({
          data: {
            user_id: item.batch.user_id,
            honor_id: item.honor_id,
            active: true,
            validate: true,
            validation_status: 'APPROVED',
            submitted_at: now,
            validated_by_id: reviewerId,
            validated_at: now,
            rejection_reason: null,
            certificate: primaryFile.file_url,
            images: item.batch.files.map((file) => file.file_url),
            date: item.completed_at!,
          },
        });

    await tx.evidence_files.createMany({
      data: item.batch.files.map((file) => ({
        user_honor_id: userHonor.user_honor_id,
        file_url: file.file_url,
        file_name: file.file_name,
        file_type: file.file_type,
        uploaded_by_id: file.uploaded_by_id,
      })),
      skipDuplicates: true,
    });

    const updatedItem = await this.markItemApproved(
      tx,
      item,
      reviewerId,
      CertificateBulkImportAppliedEntityType.USER_HONOR,
      userHonor.user_honor_id,
    );

    await this.recordEvent(
      tx,
      item.batch.batch_id,
      item.item_id,
      'ITEM_APPROVED',
      reviewerId,
      comment,
      {
        applied_entity_type: 'USER_HONOR',
        applied_entity_id: userHonor.user_honor_id,
      },
    );

    return updatedItem;
  }

  private async approveClassItem(
    tx: CertificateImportApplicationTransaction,
    item: CertificateImportItemWithBatch,
    reviewerId: string,
    dto: ApproveCertificateImportDto,
  ) {
    if (!item.class_id) {
      throw new BadRequestException('CERTIFICATE_IMPORT_ITEM_MISSING_CLASS');
    }

    await assertClassCertificateHistoricalAge(tx, {
      userId: item.batch.user_id,
      classId: item.class_id,
      completedAt: item.completed_at,
    });

    const civilDate = civilDateFromDbDate(item.completed_at);
    if (!civilDate) {
      throw new BadRequestException('CERTIFICATE_IMPORT_DATE_REQUIRED');
    }
    const civilInstant = utcCivilDate(civilDate);
    const years = await tx.ecclesiastical_years.findMany({
      where: {
        start_date: { lte: civilInstant },
        end_date: { gte: civilInstant },
      },
      select: {
        year_id: true,
        start_date: true,
        end_date: true,
        active: true,
      },
    });
    const resolution = classifyCertificateImportYear(civilDate, years);
    if (resolution.status === 'missing') {
      throw new BadRequestException('CERTIFICATE_IMPORT_YEAR_NOT_FOUND');
    }
    if (resolution.status === 'ambiguous') {
      throw new BadRequestException('CERTIFICATE_IMPORT_YEAR_AMBIGUOUS');
    }
    const year = { year_id: resolution.yearId };
    const klass = await tx.classes.findUnique({
      where: { class_id: item.class_id },
      select: { asset_code: true },
    });
    if (INSTITUTIONAL_CLASS_ASSET_CODES.has(klass?.asset_code ?? '')) {
      throw new BadRequestException(
        'CERTIFICATE_IMPORT_INSTITUTIONAL_REVIEW_REQUIRED',
      );
    }

    const now = new Date();
    const rows = await tx.enrollments.findMany({
      where: {
        user_id: item.batch.user_id,
        class_id: item.class_id,
      },
      select: {
        enrollment_id: true,
        ecclesiastical_year_id: true,
        investiture_status: true,
        investiture_date: true,
        record_kind: true,
        modified_at: true,
      },
    });
    const reconciliation: EnrollmentReconciliation = {
      enrollmentId: dto.reconcile_enrollment_id,
      expectedModifiedAt: dto.expected_modified_at,
    };
    const accredited =
      klass?.asset_code === GUIDE_MAJOR_ASSET_CODE
        ? await this.substituteGuideMajor(tx, {
            item,
            yearId: year.year_id,
            now,
            reviewerId,
            rows,
            reconciliation,
          })
        : await this.accreditHistoricalClass(tx, {
            item,
            yearId: year.year_id,
            now,
            reviewerId,
            rows,
            reconciliation,
          });

    if (accredited.recordHistory) {
      await tx.investiture_validation_history.create({
        data: {
          enrollment_id: accredited.enrollmentId,
          action: 'INVESTIDO',
          performed_by: reviewerId,
          comments:
            dto.comment ??
            accredited.historyComment ??
            'Acreditación histórica por certificado. No sustituye una ceremonia de este ciclo.',
        },
      });
    }

    const updatedItem = await this.markItemApproved(
      tx,
      item,
      reviewerId,
      CertificateBulkImportAppliedEntityType.ENROLLMENT,
      accredited.enrollmentId,
    );

    await this.recordEvent(
      tx,
      item.batch.batch_id,
      item.item_id,
      'ITEM_APPROVED',
      reviewerId,
      dto.comment,
      {
        applied_entity_type: 'ENROLLMENT',
        applied_entity_id: accredited.enrollmentId,
      },
    );

    return updatedItem;
  }

  private async accreditHistoricalClass(
    tx: CertificateImportApplicationTransaction,
    params: {
      item: CertificateImportItemWithBatch;
      yearId: number;
      now: Date;
      reviewerId: string;
      rows: ExistingClassEnrollment[];
      reconciliation?: EnrollmentReconciliation;
    },
  ): Promise<AccreditedEnrollment> {
    const sameYear = params.rows.find(
      (row) => row.ecclesiastical_year_id === params.yearId,
    );
    if (sameYear) {
      if (sameYear.investiture_status !== 'INVESTIDO') {
        return this.reconcileOperationalEnrollment(tx, {
          ...params,
          current: sameYear,
        });
      }
      this.assertReconciliationTarget(
        params.reconciliation?.enrollmentId,
        sameYear.enrollment_id,
      );
      return this.reuseOrRejectFinalFact(sameYear, params.item.completed_at);
    }
    if (params.reconciliation?.enrollmentId) {
      throw new BadRequestException('CERTIFICATE_IMPORT_ENROLLMENT_MISMATCH');
    }
    if (!params.item.class_id) {
      throw new BadRequestException('CERTIFICATE_IMPORT_ITEM_MISSING_CLASS');
    }

    const created = await tx.enrollments.create({
      data: {
        user_id: params.item.batch.user_id,
        class_id: params.item.class_id,
        ecclesiastical_year_id: params.yearId,
        enrollment_date: params.now,
        record_kind: 'HISTORICAL_CERTIFICATE',
        investiture_status: 'INVESTIDO',
        investiture_date: params.item.completed_at!,
        validated_by: params.reviewerId,
        validated_at: params.now,
        rejection_reason: null,
        locked_for_validation: true,
        active: true,
        submitted_for_validation: false,
      },
      select: { enrollment_id: true },
    });
    return { enrollmentId: created.enrollment_id, recordHistory: true };
  }

  private async substituteGuideMajor(
    tx: CertificateImportApplicationTransaction,
    params: {
      item: CertificateImportItemWithBatch;
      yearId: number;
      now: Date;
      reviewerId: string;
      rows: ExistingClassEnrollment[];
      reconciliation?: EnrollmentReconciliation;
    },
  ): Promise<AccreditedEnrollment> {
    if (params.rows.length > 1) {
      throw new BadRequestException(
        'CERTIFICATE_IMPORT_ENROLLMENT_RECONCILIATION_REQUIRED',
      );
    }
    if (params.rows.length === 0) {
      return this.accreditHistoricalClass(tx, params);
    }
    this.assertReconciliationTarget(
      params.reconciliation?.enrollmentId,
      params.rows[0].enrollment_id,
    );

    const current = params.rows[0];
    if (current.investiture_status === 'INVESTIDO') {
      return this.reuseOrRejectFinalFact(current, params.item.completed_at);
    }

    await tx.enrollments.update({
      where: { enrollment_id: current.enrollment_id },
      data: {
        ecclesiastical_year_id: params.yearId,
        record_kind: 'HISTORICAL_CERTIFICATE',
        investiture_status: 'INVESTIDO',
        investiture_date: params.item.completed_at!,
        validated_by: params.reviewerId,
        validated_at: params.now,
        rejection_reason: null,
        locked_for_validation: true,
        active: true,
        submitted_for_validation: false,
      },
    });
    return { enrollmentId: current.enrollment_id, recordHistory: true };
  }

  private assertReconciliationTarget(
    requestedId: number | undefined,
    enrollmentId: number,
  ) {
    if (requestedId !== undefined && requestedId !== enrollmentId) {
      throw new BadRequestException('CERTIFICATE_IMPORT_ENROLLMENT_MISMATCH');
    }
  }

  private async reconcileOperationalEnrollment(
    tx: CertificateImportApplicationTransaction,
    params: {
      item: CertificateImportItemWithBatch;
      now: Date;
      reviewerId: string;
      current: ExistingClassEnrollment;
      reconciliation?: EnrollmentReconciliation;
    },
  ): Promise<AccreditedEnrollment> {
    const requestedId = params.reconciliation?.enrollmentId;
    if (requestedId === undefined) {
      throw new BadRequestException(
        'CERTIFICATE_IMPORT_ENROLLMENT_RECONCILIATION_REQUIRED',
      );
    }
    if (requestedId !== params.current.enrollment_id) {
      throw new BadRequestException('CERTIFICATE_IMPORT_ENROLLMENT_MISMATCH');
    }
    const expected = params.reconciliation?.expectedModifiedAt
      ? new Date(params.reconciliation.expectedModifiedAt)
      : null;
    if (
      !expected ||
      Number.isNaN(expected.getTime()) ||
      !params.current.modified_at ||
      expected.getTime() !== params.current.modified_at.getTime()
    ) {
      throw new BadRequestException(
        'CERTIFICATE_IMPORT_ENROLLMENT_VERSION_CONFLICT',
      );
    }
    if (!params.item.class_id) {
      throw new BadRequestException('CERTIFICATE_IMPORT_ITEM_MISSING_CLASS');
    }

    const updated = await tx.enrollments.updateMany({
      where: {
        enrollment_id: params.current.enrollment_id,
        user_id: params.item.batch.user_id,
        class_id: params.item.class_id,
        ecclesiastical_year_id: params.current.ecclesiastical_year_id,
        record_kind: 'OPERATIONAL',
        investiture_status: { not: 'INVESTIDO' },
        modified_at: params.current.modified_at,
      },
      data: {
        investiture_status: 'INVESTIDO',
        investiture_date: params.item.completed_at!,
        validated_by: params.reviewerId,
        validated_at: params.now,
        rejection_reason: null,
        locked_for_validation: true,
        active: true,
        submitted_for_validation: false,
      },
    });
    if (updated.count !== 1) {
      throw new BadRequestException(
        'CERTIFICATE_IMPORT_ENROLLMENT_VERSION_CONFLICT',
      );
    }
    return {
      enrollmentId: params.current.enrollment_id,
      recordHistory: true,
      historyComment:
        'Acreditación sobre la inscripción vigente. Se conservan el progreso y la fecha de alta.',
    };
  }

  private reuseOrRejectFinalFact(
    existing: ExistingClassEnrollment,
    completedAt: Date | null | undefined,
  ): AccreditedEnrollment {
    const sameDate =
      civilDateFromDbDate(existing.investiture_date) ===
      civilDateFromDbDate(completedAt);
    if (
      existing.investiture_status === 'INVESTIDO' &&
      sameDate
    ) {
      return { enrollmentId: existing.enrollment_id, recordHistory: false };
    }
    if (existing.investiture_status === 'INVESTIDO') {
      throw new BadRequestException('CERTIFICATE_IMPORT_FINAL_DATE_CONFLICT');
    }
    throw new BadRequestException(
      'CERTIFICATE_IMPORT_ENROLLMENT_RECONCILIATION_REQUIRED',
    );
  }

  private async findSubmittedItem(
    tx: Pick<Prisma.TransactionClient, 'certificate_bulk_import_items'>,
    batchId: string,
    itemId: string,
  ): Promise<CertificateImportItemWithBatch> {
    const item = await tx.certificate_bulk_import_items.findFirst({
      where: {
        item_id: itemId,
        batch_id: batchId,
        active: true,
        OR: [
          { status: { in: REVIEWABLE_ITEM_STATUSES } },
          {
            status: CertificateBulkImportItemStatus.APPROVED,
            applied_entity_id: { not: null },
          },
        ],
      },
      include: {
        batch: {
          include: {
            files: { where: { active: true } },
          },
        },
      },
    });

    if (!item) {
      throw new NotFoundException('CERTIFICATE_IMPORT_ITEM_NOT_FOUND');
    }

    if (
      !item.applied_entity_id &&
      !REVIEWABLE_ITEM_STATUSES.includes(
        item.status as CertificateBulkImportItemStatus,
      )
    ) {
      throw new BadRequestException('CERTIFICATE_IMPORT_ITEM_NOT_REVIEWABLE');
    }

    return item;
  }

  private primaryFile(item: CertificateImportItemWithBatch) {
    const primaryFile = item.batch.files[0];
    if (!primaryFile) {
      throw new BadRequestException('CERTIFICATE_IMPORT_FILE_REQUIRED');
    }

    return primaryFile;
  }

  async resolveBatchStatus(
    tx: Pick<Prisma.TransactionClient, 'certificate_bulk_import_items'>,
    batchId: string,
  ): Promise<'SUBMITTED' | 'APPROVED' | 'NEEDS_CORRECTION'> {
    const open = await tx.certificate_bulk_import_items.count({
      where: {
        batch_id: batchId,
        active: true,
        status: { in: REVIEWABLE_ITEM_STATUSES },
      },
    });
    if (open > 0) {
      return 'SUBMITTED';
    }

    const rejected = await tx.certificate_bulk_import_items.count({
      where: {
        batch_id: batchId,
        active: true,
        status: CertificateBulkImportItemStatus.REJECTED,
      },
    });
    return rejected > 0 ? 'NEEDS_CORRECTION' : 'APPROVED';
  }

  private async markItemApproved(
    tx: CertificateImportApplicationTransaction,
    item: CertificateImportItemWithBatch,
    reviewerId: string,
    appliedEntityType: CertificateBulkImportAppliedEntityType,
    appliedEntityId: number,
  ) {
    const updatedItem = await tx.certificate_bulk_import_items.update({
      where: { item_id: item.item_id },
      data: {
        status: CertificateBulkImportItemStatus.APPROVED,
        reviewed_by_id: reviewerId,
        reviewed_at: new Date(),
        rejection_reason: null,
        applied_entity_type: appliedEntityType,
        applied_entity_id: appliedEntityId,
      },
    });

    const status = await this.resolveBatchStatus(tx, item.batch.batch_id);

    await tx.certificate_bulk_import_batches.update({
      where: { batch_id: item.batch.batch_id },
      data: {
        status,
        reviewed_at: new Date(),
      },
    });

    return updatedItem;
  }

  private async recordEvent(
    tx: Pick<PrismaService, 'certificate_bulk_import_item_events'>,
    batchId: string,
    itemId: string,
    action: string,
    performedById: string,
    comment?: string,
    payload?: Record<string, unknown>,
  ) {
    await tx.certificate_bulk_import_item_events.create({
      data: {
        batch_id: batchId,
        item_id: itemId,
        action,
        performed_by_id: performedById,
        comment,
        payload: this.toInputJson(payload),
      },
    });
  }

  private toInputJson(value: unknown): Prisma.InputJsonValue | undefined {
    if (value === undefined) {
      return undefined;
    }

    return JSON.parse(JSON.stringify(value)) as Prisma.InputJsonValue;
  }
}

import {
  BadRequestException,
  Injectable,
  Logger,
  NotFoundException,
  Optional,
} from '@nestjs/common';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';
import { PrismaService } from '../prisma/prisma.service';
import { Prisma } from '@prisma/client';
import {
  CreateCertificateBulkImportDto,
  UpdateCertificateImportItemDto,
} from './dto';
import {
  CertificateBulkImportItemStatus,
  CertificateBulkImportItemType,
} from './certificate-bulk-imports.types';
import type { CertificateOcrProvider } from './ocr/certificate-ocr.provider';
import { CERTIFICATE_OCR_PROVIDER } from './ocr/certificate-ocr.provider';
import {
  CERTIFICATE_OCR_JOB,
  CERTIFICATE_OCR_QUEUE,
} from './ocr/certificate-ocr.queue';
import { Inject } from '@nestjs/common';
import { normalizeCertificateImportFileRef } from './certificate-import-file-ref';
import {
  assertClassCertificateHistoricalAge,
  isCertificateHistoricalGateError,
} from './class-certificate-historical-age';

const INSTITUTIONAL_CLASS_ASSET_CODES = new Set(['GM-02', 'GM-03']);

@Injectable()
export class CertificateBulkImportsService {
  private readonly logger = new Logger(CertificateBulkImportsService.name);

  constructor(
    private readonly prisma: PrismaService,
    @Inject(CERTIFICATE_OCR_PROVIDER)
    private readonly ocrProvider: CertificateOcrProvider,
    @Optional()
    @InjectQueue(CERTIFICATE_OCR_QUEUE)
    private readonly ocrQueue: Pick<Queue, 'add'> | null = null,
  ) {}

  async createDraft(userId: string, dto: CreateCertificateBulkImportDto) {
    const files = (dto.files ?? []).map((file) => ({
      ...file,
      file_url: normalizeCertificateImportFileRef(file.file_url),
    }));

    const user = await this.prisma.users.findUnique({
      where: { user_id: userId },
      select: { local_field_id: true },
    });

    if (!user) {
      throw new NotFoundException('USER_NOT_FOUND');
    }

    return this.prisma.$transaction(async (tx) => {
      const batch = await tx.certificate_bulk_import_batches.create({
        data: {
          user_id: userId,
          local_field_id: user.local_field_id,
          raw_ocr_payload: this.toInputJson(dto.raw_ocr_payload),
          ...(files.length > 0
            ? {
                files: {
                  create: files.map((file) => ({
                    file_url: file.file_url,
                    file_name: file.file_name,
                    file_type: file.file_type,
                    ocr_raw_text: file.ocr_raw_text,
                    uploaded_by_id: userId,
                    upload_status: 'PENDING_UPLOAD' as const,
                  })),
                },
              }
            : {}),
        },
        include: this.batchInclude(),
      });

      if (dto.items?.length) {
        await tx.certificate_bulk_import_items.createMany({
          data: dto.items.map((item) =>
            this.toItemCreateData(batch.batch_id, item),
          ),
        });
      }

      await this.recordEvent(tx, batch.batch_id, null, 'DRAFT_CREATED', userId);

      return batch;
    });
  }

  async processOcr(userId: string, batchId: string) {
    await this.loadReadableOcrBatch(userId, batchId);
    if (!this.ocrQueue) {
      throw new BadRequestException('CERTIFICATE_IMPORT_OCR_UNAVAILABLE');
    }

    try {
      await this.ocrQueue.add(
        CERTIFICATE_OCR_JOB,
        { userId, batchId },
        {
          jobId: `certificate-ocr-${batchId}`,
          attempts: 2,
          backoff: { type: 'fixed', delay: 5_000 },
          removeOnComplete: true,
          removeOnFail: { age: 3_600, count: 20 },
        },
      );
    } catch (error) {
      const message = error instanceof Error ? error.message : '';
      if (!/already exists|already waiting|jobid/i.test(message)) {
        this.logger.error('certificate OCR enqueue failed');
        throw new BadRequestException('CERTIFICATE_IMPORT_OCR_UNAVAILABLE');
      }
      return this.getBatch(userId, batchId);
    }

    await this.recordEvent(this.prisma, batchId, null, 'OCR_QUEUED', userId, {
      queued: true,
    });
    return this.getBatch(userId, batchId);
  }

  async runQueuedOcr(userId: string, batchId: string) {
    const { batch, readable } = await this.loadReadableOcrBatch(
      userId,
      batchId,
    );
    const started = Date.now();
    const ocrResult = await this.ocrProvider.extract(
      readable.map((file) => ({
        fileUrl: file.object_key as string,
        fileName: file.file_name,
        fileType: file.file_type,
        objectKey: file.object_key,
        sizeBytes: file.size_bytes == null ? null : Number(file.size_bytes),
      })),
    );

    const stored = await this.prisma.$transaction(async (tx) => {
      const existing = await tx.certificate_bulk_import_items.findMany({
        where: { batch_id: batchId, active: true },
        select: {
          item_id: true,
          status: true,
          honor_id: true,
          class_id: true,
        },
      });
      const disposableIds = existing
        .filter(
          (item) =>
            item.status === 'NEEDS_REVIEW' && !item.honor_id && !item.class_id,
        )
        .map((item) => item.item_id);
      if (disposableIds.length > 0) {
        await tx.certificate_bulk_import_items.updateMany({
          where: { item_id: { in: disposableIds } },
          data: { active: false },
        });
      }

      if (ocrResult.items.length > 0) {
        await tx.certificate_bulk_import_items.createMany({
          data: ocrResult.items.map((item) => ({
            batch_id: batch.batch_id,
            item_type: item.type,
            detected_name: item.detectedName,
            detected_date: this.toDate(item.completedAt),
            completed_at: this.toDate(item.completedAt),
            ocr_confidence: item.confidence,
            field_confidence: this.toInputJson(item.fieldConfidence),
            status: CertificateBulkImportItemStatus.NEEDS_REVIEW,
          })),
        });
      }

      await this.recordEvent(tx, batchId, null, 'OCR_PROCESSED', userId, {
        item_count: ocrResult.items.length,
        institutional_count: ocrResult.items.filter(
          (item) => item.fieldConfidence.institutional === 1,
        ).length,
      });

      const updated = await tx.certificate_bulk_import_batches.update({
        where: { batch_id: batchId },
        data: {
          raw_ocr_payload: this.toInputJson({
            rawText: ocrResult.rawText,
            items: ocrResult.items,
          }),
        },
        include: this.batchInclude(),
      });
      return updated;
    });
    this.logger.log(
      `certificate OCR stored ${ocrResult.items.length} suggestions in ${Date.now() - started}ms`,
    );
    return stored;
  }

  private async loadReadableOcrBatch(userId: string, batchId: string) {
    const batch = await this.findOwnedBatchWithFiles(
      this.prisma,
      userId,
      batchId,
    );
    this.assertDraftLike(batch.status, 'process OCR');

    const activeFiles = batch.files.filter((file) => file.active !== false);
    for (const file of activeFiles) {
      normalizeCertificateImportFileRef(file.file_url);
    }
    const readable = activeFiles.filter(
      (file) =>
        file.upload_status === 'CONFIRMED' &&
        !!file.object_key &&
        !/^https?:\/\//i.test(file.object_key),
    );
    if (readable.length === 0) {
      throw new BadRequestException('CERTIFICATE_IMPORT_FILE_NOT_CONFIRMED');
    }
    return { batch, readable };
  }

  async getBatch(userId: string, batchId: string) {
    return this.findOwnedBatch(
      this.prisma,
      userId,
      batchId,
      this.batchInclude(),
    );
  }

  async listMine(userId: string, page = 1, limit = 20) {
    const take = Math.min(Math.max(limit, 1), 50);
    const skip = (Math.max(page, 1) - 1) * take;
    const where = { user_id: userId, active: true };
    const [items, total] = await Promise.all([
      this.prisma.certificate_bulk_import_batches.findMany({
        where,
        orderBy: { modified_at: 'desc' },
        skip,
        take,
        include: {
          files: { where: { active: true }, select: { file_id: true, upload_status: true } },
          items: { where: { active: true }, select: { item_id: true, status: true } },
        },
      }),
      this.prisma.certificate_bulk_import_batches.count({ where }),
    ]);
    return { items, total, page: Math.max(page, 1), limit: take };
  }

  async addItem(
    userId: string,
    batchId: string,
    dto: UpdateCertificateImportItemDto,
  ) {
    return this.prisma.$transaction(async (tx) => {
      const batch = await this.findOwnedBatch(tx, userId, batchId);
      this.assertDraftLike(batch.status, 'add item');
      this.assertRevision(batch.revision, dto.expected_revision);
      await this.assertCatalogChoice(tx, dto);
      await this.assertClassAgeIfReady(tx, batch.user_id, dto);
      const count = await tx.certificate_bulk_import_items.count({
        where: { batch_id: batchId, active: true },
      });
      if (count >= 100) {
        throw new BadRequestException('CERTIFICATE_IMPORT_ITEM_LIMIT');
      }
      const item = await tx.certificate_bulk_import_items.create({
        data: this.toItemCreateData(batchId, dto),
      });
      await tx.certificate_bulk_import_batches.update({
        where: { batch_id: batchId },
        data: { revision: (batch.revision ?? 0) + 1 },
      });
      await this.recordEvent(tx, batchId, item.item_id, 'ITEM_ADDED', userId);
      return item;
    });
  }

  async removeItem(userId: string, batchId: string, itemId: string) {
    return this.prisma.$transaction(async (tx) => {
      const batch = await this.findOwnedBatch(tx, userId, batchId);
      this.assertDraftLike(batch.status, 'remove item');
      const item = await this.findOwnedItem(tx, batchId, itemId);
      if (
        item.status === CertificateBulkImportItemStatus.APPROVED ||
        item.status === CertificateBulkImportItemStatus.SUBMITTED ||
        item.status === CertificateBulkImportItemStatus.RESUBMITTED
      ) {
        throw new BadRequestException('CERTIFICATE_IMPORT_ITEM_LOCKED');
      }
      await tx.certificate_bulk_import_items.update({
        where: { item_id: itemId },
        data: { active: false, revision: (item.revision ?? 0) + 1 },
      });
      await tx.certificate_bulk_import_batches.update({
        where: { batch_id: batchId },
        data: { revision: (batch.revision ?? 0) + 1 },
      });
      await this.recordEvent(tx, batchId, itemId, 'ITEM_REMOVED', userId);
      return { item_id: itemId, active: false };
    });
  }

  async updateItem(
    userId: string,
    batchId: string,
    itemId: string,
    dto: UpdateCertificateImportItemDto,
  ) {
    return this.prisma.$transaction(async (tx) => {
      const batch = await this.findOwnedBatch(tx, userId, batchId);
      this.assertDraftLike(batch.status, 'update item');
      const existing = await this.findOwnedItem(tx, batchId, itemId);
      this.assertRevision(existing.revision, dto.expected_revision);

      const merged = this.mergeItem(existing, dto);
      this.assertNotFuture(merged.completed_at);
      if (dto.mark_as_ready) {
        await this.assertCatalogChoice(tx, merged);
        await this.assertClassAgeIfReady(tx, batch.user_id, merged);
      }

      let status = dto.mark_as_ready
        ? this.isReady(merged)
          ? CertificateBulkImportItemStatus.READY
          : CertificateBulkImportItemStatus.NEEDS_REVIEW
        : existing.status;
      if (
        !dto.mark_as_ready &&
        existing.status === CertificateBulkImportItemStatus.READY &&
        merged.item_type === CertificateBulkImportItemType.CLASS
      ) {
        status = await this.readyStatusAfterClassEdit(
          tx,
          batch.user_id,
          merged,
        );
      }

      const item = await tx.certificate_bulk_import_items.update({
        where: { item_id: itemId },
        data: {
          ...this.toItemUpdateData(dto),
          ...(dto.mark_as_ready ? { status, rejection_reason: null } : { status }),
          revision: (existing.revision ?? 0) + 1,
        },
      });

      await tx.certificate_bulk_import_batches.update({
        where: { batch_id: batchId },
        data: { revision: (batch.revision ?? 0) + 1 },
      });

      await this.recordEvent(tx, batchId, itemId, 'ITEM_UPDATED', userId, {
        status,
      });

      return item;
    });
  }

  async submit(userId: string, batchId: string) {
    return this.prisma.$transaction(async (tx) => {
      const batch = await this.findOwnedBatch(tx, userId, batchId);
      this.assertDraftLike(batch.status, 'submit');

      const activeCount = await tx.certificate_bulk_import_items.count({
        where: { batch_id: batch.batch_id, active: true },
      });
      if (activeCount === 0) {
        throw new BadRequestException('CERTIFICATE_IMPORT_ITEMS_INCOMPLETE');
      }

      const confirmedFiles = await tx.certificate_bulk_import_files.count({
        where: {
          batch_id: batch.batch_id,
          active: true,
          upload_status: 'CONFIRMED',
          object_key: { not: null },
        },
      });
      if (confirmedFiles === 0) {
        throw new BadRequestException('CERTIFICATE_IMPORT_FILE_NOT_CONFIRMED');
      }

      const classItems = await tx.certificate_bulk_import_items.findMany({
        where: {
          batch_id: batch.batch_id,
          active: true,
          item_type: CertificateBulkImportItemType.CLASS,
        },
        select: {
          item_id: true,
          class: { select: { asset_code: true } },
        },
      });
      const institutionalIds = classItems
        .filter((item) =>
          INSTITUTIONAL_CLASS_ASSET_CODES.has(item.class?.asset_code ?? ''),
        )
        .map((item) => item.item_id);
      if (institutionalIds.length === activeCount) {
        throw new BadRequestException(
          'CERTIFICATE_IMPORT_INSTITUTIONAL_REVIEW_REQUIRED',
        );
      }

      const incompleteItems = await tx.certificate_bulk_import_items.findMany({
        where: {
          batch_id: batch.batch_id,
          active: true,
          item_id: { notIn: institutionalIds },
          status: {
            notIn: [
              CertificateBulkImportItemStatus.READY,
              CertificateBulkImportItemStatus.RESUBMITTED,
            ],
          },
        },
        select: { item_id: true, status: true },
      });

      if (incompleteItems.length > 0) {
        throw new BadRequestException('CERTIFICATE_IMPORT_ITEMS_INCOMPLETE');
      }

      const readyClassItems = await tx.certificate_bulk_import_items.findMany({
        where: {
          batch_id: batch.batch_id,
          active: true,
          item_type: CertificateBulkImportItemType.CLASS,
          item_id: { notIn: institutionalIds },
          status: {
            in: [
              CertificateBulkImportItemStatus.READY,
              CertificateBulkImportItemStatus.RESUBMITTED,
            ],
          },
        },
        select: {
          class_id: true,
          completed_at: true,
        },
      });
      for (const readyClassItem of readyClassItems) {
        if (!readyClassItem.class_id) {
          throw new BadRequestException(
            'CERTIFICATE_IMPORT_ITEM_MISSING_CLASS',
          );
        }
        await assertClassCertificateHistoricalAge(tx, {
          userId: batch.user_id,
          classId: readyClassItem.class_id,
          completedAt: readyClassItem.completed_at,
        });
      }

      await tx.certificate_bulk_import_items.updateMany({
        where: {
          batch_id: batch.batch_id,
          active: true,
          item_id: { notIn: institutionalIds },
          status: {
            in: [
              CertificateBulkImportItemStatus.READY,
              CertificateBulkImportItemStatus.RESUBMITTED,
            ],
          },
        },
        data: { status: CertificateBulkImportItemStatus.SUBMITTED },
      });

      await this.recordEvent(tx, batchId, null, 'BATCH_SUBMITTED', userId);

      return tx.certificate_bulk_import_batches.update({
        where: { batch_id: batch.batch_id },
        data: {
          status: 'SUBMITTED',
          submitted_at: new Date(),
          revision: (batch.revision ?? 0) + 1,
        },
        include: this.batchInclude(),
      });
    });
  }

  async resubmitItem(
    userId: string,
    batchId: string,
    itemId: string,
    dto: UpdateCertificateImportItemDto,
  ) {
    return this.prisma.$transaction(async (tx) => {
      const batch = await this.findOwnedBatch(tx, userId, batchId);
      const existingItem = await this.findOwnedItem(tx, batchId, itemId);

      if (existingItem.status !== CertificateBulkImportItemStatus.REJECTED) {
        throw new BadRequestException('CERTIFICATE_IMPORT_ITEM_NOT_REJECTED');
      }

      const merged = this.mergeItem(existingItem, dto);
      this.assertNotFuture(merged.completed_at);
      if (!this.isReady({ ...merged, mark_as_ready: true })) {
        throw new BadRequestException('CERTIFICATE_IMPORT_ITEM_INCOMPLETE');
      }
      await this.assertCatalogChoice(tx, merged);
      await this.assertClassAgeIfReady(tx, batch.user_id, {
        ...merged,
        mark_as_ready: true,
      });

      const item = await tx.certificate_bulk_import_items.update({
        where: { item_id: itemId },
        data: {
          ...this.toItemUpdateData(dto),
          status: CertificateBulkImportItemStatus.RESUBMITTED,
          rejection_reason: null,
          revision: (existingItem.revision ?? 0) + 1,
        },
      });

      await tx.certificate_bulk_import_batches.update({
        where: { batch_id: batch.batch_id },
        data: { status: 'SUBMITTED' },
      });

      await this.recordEvent(tx, batchId, itemId, 'ITEM_RESUBMITTED', userId);

      return item;
    });
  }

  private async findOwnedBatch(
    tx: Pick<
      PrismaService | Prisma.TransactionClient,
      'certificate_bulk_import_batches'
    >,
    userId: string,
    batchId: string,
    include?: Prisma.certificate_bulk_import_batchesInclude,
  ) {
    const batch = await tx.certificate_bulk_import_batches.findFirst({
      where: { batch_id: batchId, user_id: userId, active: true },
      ...(include ? { include } : {}),
    });

    if (!batch) {
      throw new NotFoundException('CERTIFICATE_IMPORT_BATCH_NOT_FOUND');
    }

    return batch;
  }

  private async findOwnedBatchWithFiles(
    tx: Pick<Prisma.TransactionClient, 'certificate_bulk_import_batches'>,
    userId: string,
    batchId: string,
  ) {
    const batch = await tx.certificate_bulk_import_batches.findFirst({
      where: { batch_id: batchId, user_id: userId, active: true },
      include: { files: true },
    });

    if (!batch) {
      throw new NotFoundException('CERTIFICATE_IMPORT_BATCH_NOT_FOUND');
    }

    return batch;
  }

  private async findOwnedItem(
    tx: Pick<
      PrismaService | Prisma.TransactionClient,
      'certificate_bulk_import_items'
    >,
    batchId: string,
    itemId: string,
  ) {
    const item = await tx.certificate_bulk_import_items.findFirst({
      where: { item_id: itemId, batch_id: batchId, active: true },
    });

    if (!item) {
      throw new NotFoundException('CERTIFICATE_IMPORT_ITEM_NOT_FOUND');
    }

    return item;
  }

  private assertDraftLike(status: string, action: string): void {
    if (!['DRAFT', 'NEEDS_CORRECTION'].includes(status)) {
      throw new BadRequestException(
        `CERTIFICATE_IMPORT_CANNOT_${action.toUpperCase().replaceAll(' ', '_')}`,
      );
    }
  }

  private toItemCreateData(
    batchId: string,
    item: UpdateCertificateImportItemDto,
  ): Prisma.certificate_bulk_import_itemsCreateManyInput {
    if (!item.item_type) {
      throw new BadRequestException('CERTIFICATE_IMPORT_ITEM_TYPE_REQUIRED');
    }

    return {
      batch_id: batchId,
      item_type: item.item_type,
      honor_id:
        item.item_type === CertificateBulkImportItemType.HONOR
          ? (item.honor_id ?? null)
          : null,
      class_id:
        item.item_type === CertificateBulkImportItemType.CLASS
          ? (item.class_id ?? null)
          : null,
      detected_name: item.detected_name,
      detected_date: this.toDate(item.detected_date),
      completed_at: this.toDate(item.completed_at),
      ocr_confidence: item.ocr_confidence,
      field_confidence: this.toInputJson(item.field_confidence),
      status: this.isReady(item)
        ? CertificateBulkImportItemStatus.READY
        : CertificateBulkImportItemStatus.NEEDS_REVIEW,
    };
  }

  private toItemUpdateData(
    dto: UpdateCertificateImportItemDto,
  ): Prisma.certificate_bulk_import_itemsUncheckedUpdateInput {
    const data: Prisma.certificate_bulk_import_itemsUncheckedUpdateInput = {};

    if (dto.item_type !== undefined) {
      data.item_type = dto.item_type;
      data.honor_id =
        dto.item_type === CertificateBulkImportItemType.HONOR
          ? (dto.honor_id ?? null)
          : null;
      data.class_id =
        dto.item_type === CertificateBulkImportItemType.CLASS
          ? (dto.class_id ?? null)
          : null;
    }

    if (dto.detected_name !== undefined) {
      data.detected_name = dto.detected_name;
    }

    if (dto.detected_date !== undefined) {
      data.detected_date = this.toDate(dto.detected_date);
    }

    if (dto.completed_at !== undefined) {
      data.completed_at = this.toDate(dto.completed_at);
    }

    if (dto.ocr_confidence !== undefined) {
      data.ocr_confidence = dto.ocr_confidence;
    }

    if (dto.field_confidence !== undefined) {
      data.field_confidence = this.toInputJson(dto.field_confidence);
    }

    return data;
  }

  private mergeItem(
    existing: {
      item_type: string;
      honor_id?: number | null;
      class_id?: number | null;
      completed_at?: Date | null;
    },
    dto: UpdateCertificateImportItemDto,
  ) {
    const itemType = dto.item_type ?? existing.item_type;
    return {
      item_type: itemType,
      honor_id:
        itemType === CertificateBulkImportItemType.HONOR
          ? (dto.honor_id ?? existing.honor_id ?? null)
          : null,
      class_id:
        itemType === CertificateBulkImportItemType.CLASS
          ? (dto.class_id ?? existing.class_id ?? null)
          : null,
      completed_at: dto.completed_at ?? this.civilDate(existing.completed_at),
      mark_as_ready: dto.mark_as_ready,
    };
  }

  private assertRevision(current: number | null | undefined, expected?: number) {
    if (expected === undefined) return;
    if (expected !== (current ?? 0)) {
      throw new BadRequestException('CERTIFICATE_IMPORT_REVISION_CONFLICT');
    }
  }

  private assertNotFuture(completedAt?: string) {
    if (!completedAt) return;
    const today = new Date().toISOString().slice(0, 10);
    if (completedAt > today) {
      throw new BadRequestException('CERTIFICATE_IMPORT_DATE_IN_FUTURE');
    }
  }

  private async readyStatusAfterClassEdit(
    tx: Prisma.TransactionClient,
    userId: string,
    item: {
      item_type?: string | null;
      class_id?: number | null;
      completed_at?: string | null;
    },
  ): Promise<CertificateBulkImportItemStatus> {
    if (!this.isReady({ ...item, mark_as_ready: true }) || !item.class_id) {
      return CertificateBulkImportItemStatus.NEEDS_REVIEW;
    }
    try {
      await assertClassCertificateHistoricalAge(tx, {
        userId,
        classId: item.class_id,
        completedAt: item.completed_at,
      });
      return CertificateBulkImportItemStatus.READY;
    } catch (error) {
      if (!isCertificateHistoricalGateError(error)) throw error;
      return CertificateBulkImportItemStatus.NEEDS_REVIEW;
    }
  }

  private async assertClassAgeIfReady(
    tx: Prisma.TransactionClient,
    userId: string,
    item: {
      item_type?: string | null;
      class_id?: number | null;
      completed_at?: string | null;
      mark_as_ready?: boolean;
    },
  ) {
    if (
      item.item_type !== CertificateBulkImportItemType.CLASS ||
      !item.class_id ||
      !this.isReady({ ...item, mark_as_ready: true })
    ) {
      return;
    }
    if (!item.mark_as_ready) {
      return;
    }
    await assertClassCertificateHistoricalAge(tx, {
      userId,
      classId: item.class_id,
      completedAt: item.completed_at,
    });
  }

  private async assertCatalogChoice(
    tx: Prisma.TransactionClient,
    item: {
      item_type?: string | null;
      honor_id?: number | null;
      class_id?: number | null;
    },
  ) {
    if (
      item.item_type === CertificateBulkImportItemType.HONOR &&
      item.honor_id
    ) {
      const honor = await tx.honors.findUnique({
        where: { honor_id: item.honor_id },
        select: { active: true },
      });
      if (!honor?.active) {
        throw new BadRequestException('CERTIFICATE_IMPORT_CATALOG_NOT_FOUND');
      }
    }

    if (
      item.item_type === CertificateBulkImportItemType.CLASS &&
      item.class_id
    ) {
      const klass = await tx.classes.findUnique({
        where: { class_id: item.class_id },
        select: { active: true, asset_code: true },
      });
      const institutional = INSTITUTIONAL_CLASS_ASSET_CODES.has(
        klass?.asset_code ?? '',
      );
      if (!klass || (!klass.active && !institutional)) {
        throw new BadRequestException('CERTIFICATE_IMPORT_CATALOG_NOT_FOUND');
      }
    }
  }

  private civilDate(value?: Date | string | null): string | undefined {
    if (!value) return undefined;
    if (typeof value === 'string') return value.slice(0, 10);
    return value.toISOString().slice(0, 10);
  }

  private isReady(dto: {
    item_type?: string | null;
    honor_id?: number | null;
    class_id?: number | null;
    completed_at?: string | null;
    mark_as_ready?: boolean;
  }): boolean {
    if (!dto.mark_as_ready || !dto.completed_at) {
      return false;
    }

    if (dto.item_type === CertificateBulkImportItemType.HONOR) {
      return Number.isInteger(dto.honor_id) && Number(dto.honor_id) > 0;
    }

    if (dto.item_type === CertificateBulkImportItemType.CLASS) {
      return Number.isInteger(dto.class_id) && Number(dto.class_id) > 0;
    }

    return false;
  }

  private toDate(value?: string): Date | undefined {
    return value ? new Date(`${value}T00:00:00.000Z`) : undefined;
  }

  private toInputJson(value: unknown): Prisma.InputJsonValue | undefined {
    if (value === undefined) {
      return undefined;
    }

    return JSON.parse(JSON.stringify(value)) as Prisma.InputJsonValue;
  }

  private batchInclude() {
    return {
      files: true,
      items: {
        where: { active: true },
        orderBy: { created_at: 'asc' as const },
      },
      events: {
        orderBy: { created_at: 'asc' as const },
      },
    };
  }

  private async recordEvent(
    tx: Pick<PrismaService, 'certificate_bulk_import_item_events'>,
    batchId: string,
    itemId: string | null,
    action: string,
    performedById: string,
    payload?: Record<string, unknown>,
  ) {
    await tx.certificate_bulk_import_item_events.create({
      data: {
        batch_id: batchId,
        item_id: itemId,
        action,
        performed_by_id: performedById,
        payload: this.toInputJson(payload),
      },
    });
  }
}

import {
  BadRequestException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { PrismaService } from '../prisma/prisma.service';
import {
  civilDateFromDbDate,
  classifyCertificateImportYear,
  utcCivilDate,
} from './certificate-import-year-resolver.service';
import { assertClassCertificateHistoricalAge } from './class-certificate-historical-age';
import type { CreateInstitutionalCertificateRequestDto } from './dto/create-institutional-certificate-request.dto';
import type {
  ApproveInstitutionalCertificateRequestDto,
  RejectInstitutionalCertificateRequestDto,
} from './dto/review-institutional-certificate-request.dto';

type InstitutionalStore = Pick<
  Prisma.TransactionClient,
  | 'institutional_certificate_requests'
  | 'institutional_certificate_request_events'
  | '$queryRawUnsafe'
>;

const INSTITUTIONAL_ASSET_CODES = new Set(['GM-02', 'GM-03']);
const OPEN_STATUSES = ['PENDING_REVIEW', 'APPROVED'] as const;

type RequestRow = {
  request_id: string;
  user_id: string;
  class_id: number;
  file_id: string;
  batch_id?: string | null;
  status: string;
  revision: number;
  completed_at: Date;
  ecclesiastical_year_id: number | null;
  decision_reason: string | null;
  reviewed_at: Date | null;
  class?: { asset_code: string | null; name: string } | null;
  user?: {
    name: string | null;
    paternal_last_name: string | null;
    maternal_last_name: string | null;
  } | null;
  events?: Array<{
    event_id: string;
    action: string;
    comment: string | null;
    revision: number;
    created_at: Date;
  }>;
};

const REQUEST_INCLUDE = {
  class: { select: { asset_code: true, name: true } },
  user: {
    select: { name: true, paternal_last_name: true, maternal_last_name: true },
  },
  events: { orderBy: { created_at: 'asc' as const } },
} satisfies Prisma.institutional_certificate_requestsInclude;

const REVIEW_STATUSES = new Set(['PENDING_REVIEW', 'APPROVED', 'REJECTED']);

function isOpenRequestConflict(error: unknown): boolean {
  return (
    typeof error === 'object' &&
    error !== null &&
    'code' in error &&
    (error as { code?: string }).code === 'P2002'
  );
}

@Injectable()
export class InstitutionalCertificateRequestsService {
  constructor(private readonly prisma: PrismaService) {}

  async submit(userId: string, dto: CreateInstitutionalCertificateRequestDto) {
    const completedAt = utcCivilDate(dto.completed_at);
    const klass = await this.prisma.classes.findUnique({
      where: { class_id: dto.class_id },
      select: { class_id: true, asset_code: true, name: true, active: true },
    });
    if (!INSTITUTIONAL_ASSET_CODES.has(klass?.asset_code ?? '')) {
      throw new BadRequestException(
        'CERTIFICATE_IMPORT_CLASS_NOT_INSTITUTIONAL',
      );
    }

    const file = await this.prisma.certificate_bulk_import_files.findFirst({
      where: { file_id: dto.file_id, active: true },
      select: {
        file_id: true,
        upload_status: true,
        object_key: true,
        batch: { select: { user_id: true, batch_id: true } },
      },
    });
    if (!file || file.batch.user_id !== userId) {
      throw new NotFoundException('CERTIFICATE_IMPORT_FILE_NOT_FOUND');
    }
    if (file.upload_status !== 'CONFIRMED' || !file.object_key) {
      throw new BadRequestException('CERTIFICATE_IMPORT_FILE_NOT_CONFIRMED');
    }

    const existing = await this.prisma.institutional_certificate_requests.findFirst({
      where: {
        user_id: userId,
        class_id: dto.class_id,
        file_id: dto.file_id,
        completed_at: completedAt,
        active: true,
        status: { in: [...OPEN_STATUSES] },
      },
      include: REQUEST_INCLUDE,
    });
    if (existing) {
      return this.toView(existing, await this.blockers(existing.completed_at));
    }

    const predecessor =
      await this.prisma.institutional_certificate_requests.findFirst({
        where: {
          user_id: userId,
          class_id: dto.class_id,
          file_id: dto.file_id,
          status: 'REJECTED',
          active: true,
        },
        orderBy: { created_at: 'desc' },
        select: { request_id: true },
      });

    try {
      const created = await this.prisma.$transaction(async (tx) => {
        const age = await assertClassCertificateHistoricalAge(tx, {
          userId,
          classId: dto.class_id,
          completedAt: completedAt,
        });
        const request = await tx.institutional_certificate_requests.create({
          data: {
            user_id: userId,
            class_id: dto.class_id,
            file_id: dto.file_id,
            batch_id: file.batch.batch_id,
            source: dto.source ?? 'MANUAL',
            completed_at: completedAt,
            ecclesiastical_year_id: age.yearId,
            predecessor_request_id: predecessor?.request_id,
          },
          include: REQUEST_INCLUDE,
        });
        await tx.certificate_bulk_import_files.update({
          where: { file_id: file.file_id },
          data: { jurisdiction: 'INSTITUTIONAL' },
        });
        await tx.institutional_certificate_request_events.create({
          data: {
            request_id: request.request_id,
            action: 'REQUEST_SUBMITTED',
            performed_by_id: userId,
            revision: 0,
          },
        });
        return request;
      });

      return this.toView(created, await this.blockers(created.completed_at));
    } catch (error) {
      if (!isOpenRequestConflict(error)) {
        throw error;
      }
      const winner =
        await this.prisma.institutional_certificate_requests.findFirst({
          where: {
            user_id: userId,
            class_id: dto.class_id,
            file_id: dto.file_id,
            completed_at: completedAt,
            active: true,
            status: { in: [...OPEN_STATUSES] },
          },
          include: REQUEST_INCLUDE,
        });
      if (!winner) {
        throw error;
      }
      return this.toView(winner, await this.blockers(winner.completed_at));
    }
  }

  async listMine(userId: string, page = 1, limit = 20) {
    return this.list({ user_id: userId }, page, limit);
  }

  async getMine(userId: string, requestId: string) {
    const request = await this.findVisible(requestId);
    if (request.user_id !== userId) {
      throw new NotFoundException('CERTIFICATE_IMPORT_REQUEST_NOT_FOUND');
    }
    return this.toView(request, await this.blockers(request.completed_at));
  }

  async listForReview(
    reviewerId: string,
    page = 1,
    limit = 20,
    filters: { status?: string; classId?: number; q?: string } = {},
  ) {
    await this.assertSuperAdmin(reviewerId);
    if (filters.status && !REVIEW_STATUSES.has(filters.status)) {
      throw new BadRequestException('CERTIFICATE_IMPORT_STATUS_INVALID');
    }
    const q = filters.q?.trim();
    return this.list(
      {
        ...(filters.status ? { status: filters.status as 'PENDING_REVIEW' } : {}),
        ...(filters.classId ? { class_id: filters.classId } : {}),
        ...(q
          ? {
              user: {
                OR: [
                  { name: { contains: q, mode: 'insensitive' as const } },
                  {
                    paternal_last_name: {
                      contains: q,
                      mode: 'insensitive' as const,
                    },
                  },
                  {
                    maternal_last_name: {
                      contains: q,
                      mode: 'insensitive' as const,
                    },
                  },
                ],
              },
            }
          : {}),
      },
      page,
      limit,
    );
  }

  async getForReview(reviewerId: string, requestId: string) {
    await this.assertSuperAdmin(reviewerId);
    const request = await this.findVisible(requestId);
    return this.toView(request, await this.blockers(request.completed_at));
  }

  async approve(
    reviewerId: string,
    requestId: string,
    dto: ApproveInstitutionalCertificateRequestDto,
  ) {
    await this.assertSuperAdmin(reviewerId);
    return this.prisma.$transaction(async (tx) => {
      if (typeof tx.$queryRawUnsafe === 'function') {
        await tx.$queryRawUnsafe(
          `SELECT request_id FROM institutional_certificate_requests
           WHERE request_id = $1::uuid
           FOR UPDATE`,
          requestId,
        );
      }
      const current = await this.findVisible(requestId, tx);
      if (current.status === 'APPROVED') {
        return this.toView(current, []);
      }
      if (current.status === 'REJECTED') {
        throw new BadRequestException('CERTIFICATE_IMPORT_DECISION_IMMUTABLE');
      }
      const age = await assertClassCertificateHistoricalAge(tx, {
        userId: current.user_id,
        classId: current.class_id,
        completedAt: current.completed_at,
      });
      return this.decide(tx, reviewerId, current, dto.expected_revision, {
        status: 'APPROVED',
        ecclesiastical_year_id: age.yearId,
        decision_reason: dto.comment ?? null,
        action: 'REQUEST_APPROVED',
      });
    });
  }

  async reject(
    reviewerId: string,
    requestId: string,
    dto: RejectInstitutionalCertificateRequestDto,
  ) {
    await this.assertSuperAdmin(reviewerId);
    const current = await this.findVisible(requestId);
    if (current.status === 'REJECTED') {
      return this.toView(current, await this.blockers(current.completed_at));
    }
    if (current.status === 'APPROVED') {
      throw new BadRequestException('CERTIFICATE_IMPORT_DECISION_IMMUTABLE');
    }
    if (!dto.reason?.trim()) {
      throw new BadRequestException('CERTIFICATE_IMPORT_REJECTION_REASON_REQUIRED');
    }

    return this.decide(
      this.prisma,
      reviewerId,
      current,
      dto.expected_revision,
      {
        status: 'REJECTED',
        decision_reason: dto.reason.trim(),
        action: 'REQUEST_REJECTED',
      },
    );
  }

  private async decide(
    db: InstitutionalStore,
    reviewerId: string,
    current: RequestRow,
    expectedRevision: number,
    change: {
      status: 'APPROVED' | 'REJECTED';
      ecclesiastical_year_id?: number;
      decision_reason: string | null;
      action: string;
    },
  ) {
    if (current.revision !== expectedRevision) {
      throw new BadRequestException('CERTIFICATE_IMPORT_REVISION_CONFLICT');
    }

    const updated = await db.institutional_certificate_requests.updateMany({
      where: {
        request_id: current.request_id,
        status: 'PENDING_REVIEW',
        revision: expectedRevision,
      },
      data: {
        status: change.status,
        ecclesiastical_year_id: change.ecclesiastical_year_id,
        decision_reason: change.decision_reason,
        reviewed_by_id: reviewerId,
        reviewed_at: new Date(),
        revision: expectedRevision + 1,
      },
    });
    if (updated.count !== 1) {
      throw new BadRequestException('CERTIFICATE_IMPORT_REVISION_CONFLICT');
    }

    await db.institutional_certificate_request_events.create({
      data: {
        request_id: current.request_id,
        action: change.action,
        performed_by_id: reviewerId,
        comment: change.decision_reason,
        revision: expectedRevision + 1,
      },
    });

    const request = await this.findVisible(current.request_id, db);
    return this.toView(request, []);
  }

  private async list(
    where: Prisma.institutional_certificate_requestsWhereInput,
    page: number,
    limit: number,
  ) {
    const take = Math.min(Math.max(limit, 1), 50);
    const currentPage = Math.max(page, 1);
    const [rows, total] = await Promise.all([
      this.prisma.institutional_certificate_requests.findMany({
        where: { ...where, active: true },
        orderBy: { created_at: 'desc' },
        skip: (currentPage - 1) * take,
        take,
        include: REQUEST_INCLUDE,
      }),
      this.prisma.institutional_certificate_requests.count({
        where: { ...where, active: true },
      }),
    ]);
    return {
      items: rows.map((row) => this.toView(row, [])),
      total,
      page: currentPage,
      limit: take,
    };
  }

  private async findVisible(
    requestId: string,
    db: InstitutionalStore = this.prisma,
  ): Promise<RequestRow> {
    const request = await db.institutional_certificate_requests.findFirst({
      where: { request_id: requestId, active: true },
      include: REQUEST_INCLUDE,
    });
    if (!request) {
      throw new NotFoundException('CERTIFICATE_IMPORT_REQUEST_NOT_FOUND');
    }
    return request;
  }

  private async assertSuperAdmin(userId: string) {
    const user = await this.prisma.users.findUnique({
      where: { user_id: userId },
      select: {
        users_roles: {
          where: { active: true },
          select: { roles: { select: { role_name: true } } },
        },
      },
    });
    const roles = new Set(
      (user?.users_roles ?? []).map((entry) =>
        entry.roles.role_name.toLowerCase(),
      ),
    );
    if (!roles.has('super-admin')) {
      throw new ForbiddenException('CERTIFICATE_IMPORT_INSTITUTIONAL_FORBIDDEN');
    }
  }

  private async resolveYearId(civilDate: string): Promise<number | null> {
    if (!civilDate) return null;
    const instant = utcCivilDate(civilDate);
    const years = await this.prisma.ecclesiastical_years.findMany({
      where: { start_date: { lte: instant }, end_date: { gte: instant } },
      select: { year_id: true, start_date: true, end_date: true, active: true },
    });
    const resolution = classifyCertificateImportYear(civilDate, years);
    return resolution.status === 'resolved' ? resolution.yearId : null;
  }

  private async blockers(completedAt: Date): Promise<string[]> {
    const civilDate = civilDateFromDbDate(completedAt);
    if (!civilDate) return ['CERTIFICATE_IMPORT_DATE_REQUIRED'];
    const instant = utcCivilDate(civilDate);
    const years = await this.prisma.ecclesiastical_years.findMany({
      where: { start_date: { lte: instant }, end_date: { gte: instant } },
      select: { year_id: true, start_date: true, end_date: true, active: true },
    });
    const resolution = classifyCertificateImportYear(civilDate, years);
    if (resolution.status === 'resolved') return [];
    return [resolution.code];
  }

  private toView(request: RequestRow, approvalBlockers: string[]) {
    return {
      request_id: request.request_id,
      user_id: request.user_id,
      class_id: request.class_id,
      asset_code: request.class?.asset_code ?? null,
      class_name: request.class?.name ?? null,
      file_id: request.file_id,
      batch_id: request.batch_id ?? null,
      status: request.status,
      revision: request.revision,
      completed_at: civilDateFromDbDate(request.completed_at),
      ecclesiastical_year_id: request.ecclesiastical_year_id,
      decision_reason: request.decision_reason,
      reviewed_at: request.reviewed_at,
      applicant_name: [
        request.user?.name,
        request.user?.paternal_last_name,
        request.user?.maternal_last_name,
      ]
        .filter(Boolean)
        .join(' '),
      approval_blockers: approvalBlockers,
      enrollment_created: false,
      events: (request.events ?? []).map((event) => ({
        event_id: event.event_id,
        action: event.action,
        comment: event.comment,
        revision: event.revision,
        created_at: event.created_at,
      })),
    };
  }
}

import { Injectable } from '@nestjs/common';
import {
  AppForbiddenException,
  AppNotFoundException,
} from '../common/errors/app.exception';
import { ErrorCode } from '../common/errors/error-codes';
import { AuthorizationContextService } from '../common/services/authorization-context.service';
import { CoordinationService } from '../coordination/coordination.service';
import { PrismaService } from '../prisma/prisma.service';
import { ClassRequirementEligibilityService } from './class-requirement-eligibility.service';

const SECTION_WIDE_ROLE_NAMES = new Set([
  'director',
  'deputy-director',
  'secretary',
  'secretary-treasurer',
]);

const GLOBAL_PROGRESS_SCOPE_ROLES = [
  'super-admin',
  'admin',
  'assistant-admin',
];

const COORDINATOR_PROGRESS_SCOPE_ROLES = [
  'coordinator',
  'zone-coordinator',
  'general-coordinator',
];

export type ProgressScopeAccessLevel = 'section' | 'assigned';

export type ProgressScopeClass = {
  class_id: number;
  name: string;
  club_type_id: number;
  access_level: ProgressScopeAccessLevel;
};

export type ProgressScopeResult = {
  club_section_id: number;
  club_type_id: number;
  ecclesiastical_year_id: number;
  access_level: ProgressScopeAccessLevel;
  classes: ProgressScopeClass[];
};

export type ClassMemberProgress = {
  user_id: string;
  name: string;
  enrollment_id: number;
  class_id: number;
  ecclesiastical_year_id: number;
  investiture_status: string;
  cross_type_enrollment: boolean;
  completed_sections: number;
  total_sections: number;
  overall_progress: number;
};

export type ClassMembersProgressResult = {
  club_section_id: number;
  club_type_id: number;
  class_id: number;
  ecclesiastical_year_id: number;
  access_level: ProgressScopeAccessLevel;
  members: ClassMemberProgress[];
};

export type GetProgressScopeParams = {
  actorUserId: string;
  clubId: number;
  sectionId: number;
  ecclesiasticalYearId?: number;
};

export type GetClassMembersProgressParams = GetProgressScopeParams & {
  classId: number;
};

@Injectable()
export class ClassProgressScopeService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly authorizationContext: AuthorizationContextService,
    private readonly coordinationService: CoordinationService,
    private readonly requirementEligibility: ClassRequirementEligibilityService,
  ) {}

  async getProgressScope(
    params: GetProgressScopeParams,
  ): Promise<ProgressScopeResult> {
    const ecclesiasticalYearId = await this.resolveEcclesiasticalYearId(
      params.ecclesiasticalYearId,
    );
    const section = await this.resolveSection(params.clubId, params.sectionId);

    const hasGlobalAccess = await this.authorizationContext.hasAnyGlobalRole(
      params.actorUserId,
      GLOBAL_PROGRESS_SCOPE_ROLES,
    );
    const hasCoordinatorSectionAccess =
      (await this.authorizationContext.hasAnyGlobalRole(
        params.actorUserId,
        COORDINATOR_PROGRESS_SCOPE_ROLES,
      )) &&
      (
        await this.coordinationService.getEffectiveCoordinatorSectionIds(
          params.actorUserId,
        )
      ).includes(params.sectionId);
    const hasSectionWideAccess =
      hasGlobalAccess ||
      hasCoordinatorSectionAccess ||
      (await this.hasSectionWideAccess({
        actorUserId: params.actorUserId,
        sectionId: params.sectionId,
        ecclesiasticalYearId,
      }));

    if (hasSectionWideAccess) {
      const classes = await this.prisma.classes.findMany({
        where: {
          active: true,
          club_type_id: section.club_type_id,
        },
        select: {
          class_id: true,
          name: true,
          club_type_id: true,
        },
        orderBy: [{ display_order: 'asc' }, { class_id: 'asc' }],
      });

      return {
        club_section_id: section.club_section_id,
        club_type_id: section.club_type_id,
        ecclesiastical_year_id: ecclesiasticalYearId,
        access_level: 'section',
        classes: classes.map((row) => ({
          class_id: row.class_id,
          name: row.name,
          club_type_id: row.club_type_id,
          access_level: 'section',
        })),
      };
    }

    const assignments = await this.prisma.class_counselor_assignments.findMany({
      where: {
        user_id: params.actorUserId,
        club_section_id: params.sectionId,
        ecclesiastical_year_id: ecclesiasticalYearId,
        active: true,
      },
      select: {
        class_id: true,
        classes: {
          select: {
            class_id: true,
            name: true,
            club_type_id: true,
            active: true,
            display_order: true,
          },
        },
      },
      orderBy: [{ created_at: 'asc' }, { class_id: 'asc' }],
    });

    const seenClassIds = new Set<number>();
    const classes = assignments
      .map((assignment) => assignment.classes)
      .filter((klass) => klass.active)
      .filter((klass) => {
        if (seenClassIds.has(klass.class_id)) {
          return false;
        }

        seenClassIds.add(klass.class_id);
        return true;
      });

    return {
      club_section_id: section.club_section_id,
      club_type_id: section.club_type_id,
      ecclesiastical_year_id: ecclesiasticalYearId,
      access_level: 'assigned',
      classes: classes.map((row) => ({
        class_id: row.class_id,
        name: row.name,
        club_type_id: row.club_type_id,
        access_level: 'assigned',
      })),
    };
  }

  async getClassMembersProgress(
    params: GetClassMembersProgressParams,
  ): Promise<ClassMembersProgressResult> {
    const scope = await this.getProgressScope({
      actorUserId: params.actorUserId,
      clubId: params.clubId,
      sectionId: params.sectionId,
      ecclesiasticalYearId: params.ecclesiasticalYearId,
    });

    const accessibleClass = scope.classes.find(
      (klass) => klass.class_id === params.classId,
    );

    if (!accessibleClass) {
      throw new AppForbiddenException(ErrorCode.GUARD_PERMISSION_DENIED);
    }

    const enrollments = await this.prisma.enrollments.findMany({
      where: {
        class_id: params.classId,
        ecclesiastical_year_id: scope.ecclesiastical_year_id,
        active: true,
        record_kind: 'OPERATIONAL',
        OR: [
          // Regular section members
          {
            users: {
              club_role_assignments: {
                some: {
                  club_section_id: scope.club_section_id,
                  ecclesiastical_year_id: scope.ecclesiastical_year_id,
                  active: true,
                  status: 'active',
                },
              },
            },
          },
          // Cross-type enrollments: GM catching up in AV/CQ in another section
          // of the same club (cross_type_enrollment=true marks these rows).
          {
            cross_type_enrollment: true,
            users: {
              club_role_assignments: {
                some: {
                  ecclesiastical_year_id: scope.ecclesiastical_year_id,
                  active: true,
                  status: 'active',
                  club_sections: { main_club_id: params.clubId },
                },
              },
            },
          },
        ],
      },
      select: {
        enrollment_id: true,
        user_id: true,
        class_id: true,
        ecclesiastical_year_id: true,
        investiture_status: true,
        cross_type_enrollment: true,
        users: {
          select: {
            user_id: true,
            name: true,
            paternal_last_name: true,
            maternal_last_name: true,
          },
        },
      },
      orderBy: [{ users: { name: 'asc' } }, { user_id: 'asc' }],
    });

    if (enrollments.length === 0) {
      return {
        club_section_id: scope.club_section_id,
        club_type_id: scope.club_type_id,
        class_id: params.classId,
        ecclesiastical_year_id: scope.ecclesiastical_year_id,
        access_level: scope.access_level,
        members: [],
      };
    }

    const eligibilityByEnrollment =
      await this.requirementEligibility.calculateForEnrollments(
        enrollments.map((enrollment) => enrollment.enrollment_id),
      );
    const summaries = enrollments.map((enrollment) => {
      const eligibility = eligibilityByEnrollment.get(enrollment.enrollment_id);
      return {
        enrollment_id: enrollment.enrollment_id,
        completed: eligibility?.investiture_progress.completed ?? 0,
        total: eligibility?.investiture_progress.total ?? 0,
        overall: eligibility?.overall_progress ?? 0,
      };
    });
    const summaryByEnrollment = new Map(
      summaries.map((summary) => [summary.enrollment_id, summary]),
    );

    return {
      club_section_id: scope.club_section_id,
      club_type_id: scope.club_type_id,
      class_id: params.classId,
      ecclesiastical_year_id: scope.ecclesiastical_year_id,
      access_level: scope.access_level,
      members: enrollments.map((enrollment) => {
        const summary = summaryByEnrollment.get(enrollment.enrollment_id);
        const completed_sections = summary?.completed ?? 0;
        const total_sections = summary?.total ?? 0;
        const overall_progress = summary?.overall ?? 0;

        return {
          user_id: enrollment.user_id,
          name: enrollment.users?.name ?? '',
          enrollment_id: enrollment.enrollment_id,
          class_id: enrollment.class_id,
          ecclesiastical_year_id: enrollment.ecclesiastical_year_id,
          investiture_status: enrollment.investiture_status,
          cross_type_enrollment: enrollment.cross_type_enrollment,
          completed_sections,
          total_sections,
          overall_progress,
        };
      }),
    };
  }

  private async resolveEcclesiasticalYearId(
    ecclesiasticalYearId?: number,
  ): Promise<number> {
    if (ecclesiasticalYearId !== undefined) {
      return ecclesiasticalYearId;
    }

    const year = await this.prisma.ecclesiastical_years.findFirst({
      where: {
        start_date: { lte: new Date() },
        end_date: { gte: new Date() },
      },
      select: {
        year_id: true,
      },
      orderBy: { start_date: 'desc' },
    });

    if (!year) {
      throw new AppNotFoundException(ErrorCode.CLASS_ACTIVE_YEAR_NOT_FOUND);
    }

    return year.year_id;
  }

  private async resolveSection(clubId: number, sectionId: number): Promise<{
    club_section_id: number;
    club_type_id: number;
  }> {
    const section = await this.prisma.club_sections.findFirst({
      where: {
        club_section_id: sectionId,
        main_club_id: clubId,
        active: true,
      },
      select: {
        club_section_id: true,
        club_type_id: true,
      },
    });

    if (!section) {
      throw new AppNotFoundException(ErrorCode.CLASS_COUNSELOR_SECTION_NOT_FOUND);
    }

    return section;
  }

  private async hasSectionWideAccess(params: {
    actorUserId: string;
    sectionId: number;
    ecclesiasticalYearId: number;
  }): Promise<boolean> {
    const assignment = await this.prisma.club_role_assignments.findFirst({
      where: {
        user_id: params.actorUserId,
        club_section_id: params.sectionId,
        ecclesiastical_year_id: params.ecclesiasticalYearId,
        active: true,
        roles: {
          role_name: {
            in: Array.from(SECTION_WIDE_ROLE_NAMES),
          },
        },
      },
      select: {
        assignment_id: true,
      },
    });

    return Boolean(assignment);
  }
}

